import itertools

def count_good_paths(grid):
    n = len(grid)
    S = set()
    for r in range(n):
        for c in range(n):
            is_good_start = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if grid[nr][nc] < grid[r][c]:
                        is_good_start = False
                        break
            if is_good_start:
                S.add((r, c))

    memo = {}
    def W(r, c):
        if (r, c) in memo:
            return memo[(r, c)]
        res = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] > grid[r][c]:
                    res += W(nr, nc)
        memo[(r, c)] = res
        return res

    total_paths = 0
    for r, c in S:
        total_paths += W(r, c)
    return total_paths

n = 2
min_paths = float('inf')
for p in itertools.permutations(range(1, 5)):
    grid = [p[:2], p[2:]]
    min_paths = min(min_paths, count_good_paths(grid))
print(min_paths)
